mapper.select:
/* Comment.findCommentList */
select
	row_number() over() as num,
	a.*
from (
	select
		*
	from 
		comment
	where 1=1

	and (
		writer like concat('%', #{searchText}, '%')
		or comment like concat('%', #{searchText}, '%')
	)


	order by 


				comment_id ${orderType}


				comm_id ${orderType}


				comment_id desc



	limit #{firstIndex}, #{recordCountPerPage}
) a
